{"type": "tool_use", "name": "write_file", "tool_call_id": "67e49BJGTtI1SlODuxOcfg2uJsbvHZiH", "input": {"path": "build_summary.py", "content": "import csv, json, glob, os

files = sorted(glob.glob("sales_2026-*.csv"))
assert len(files) == 12, f"expected 12 files, got {len(files)}"

months = {}   # YYYY-MM -> {"rows_used", "revenue"}
region_rev = {}  # region -> total revenue
skipped = 0

for f in files:
    mm = os.path.basename(f)  # e.g. sales_2026-01.csv
    key = mm[7:10] + "-" + mm[11:13]  # YYYY-MM

    with open(f, newline="") as fh:
        reader = csv.DictReader(fh)
        used = 0
        for row in reader:
            qty = (row.get("qty") or "").strip()
            if qty == "":
                skipped += 1
                continue
            try:
                qty_v = float(qty)
            except ValueError:
                skipped += 1
                continue
            try:
                price_v = float((row.get("unit_price") or "").strip())
            except ValueError:
                skipped += 1
                continue
            region = (row.get("region") or "").strip()
            rev = qty_v * price_v
            months[key]["rows_used"] = months[key].get("rows_used", 0) + 1
            months[key]["revenue"] = months[key].get("revenue", 0.0) + rev
            region_rev[region] = region_rev.get(region, 0.0) + rev
            used += 1

# round per-month revenue
for key in months:
    months[key]["revenue"] = round(months[key]["revenue"], 2)

# top region overall (round to 2 decimals)
top_region = min(region_rev.items(), key=lambda kv: kv[1])  # placeholder
top_region = max(region_rev.items(), key=lambda kv: kv[1])
top_region = {"region": top_region[0], "revenue": round(top_region[1], 2)}

summary = {
    "months": months,
    "skipped_rows": skipped,
    "top_region": top_region,
}

with open("summary.json", "w") as fh:
    json.dump(summary, fh, indent=2)

print("skipped_rows:", skipped)
print("per-month rows_used:", {k: months[k]["rows_used"] for k in sorted(months)})
print("region totals:", {k: round(v,2) for k,v in sorted(region_rev.items())})
print("top_region:", top_region)
print("total revenue:", round(sum(region_rev.values()),2))
